import{_ as e,o as a,c as d,l as s,t as o,N as r}from"./chunks/framework.Bbd9fWQx.js";const k=JSON.parse('{"title":"cksum | x-cmd man (man1) | compute and verify file checksums","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | cksum - compute and verify file checksums","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"cksum | x-cmd man (man1) | compute and verify file checksums"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | cksum - compute and verify file checksums"}]]},"headers":[],"params":{"isMan":true,"man":"cksum","category":"man1","desc":"compute and verify file checksums"},"relativePath":"man1/cksum.md","filePath":"man1/cksum.md"}'),n={name:"man1/cksum.md"},i={class:"visually-hidden"},l=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>cksum - compute and verify file checksums</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>cksum</strong> [<em>OPTION</em>]... [<em>FILE</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Print or verify checksums. By default use the 32 bit CRC algorithm.</p><p>With no FILE, or when FILE is -, read standard input.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-a</strong>, <strong>--algorithm</strong>=<em>TYPE</em></dt><dd>select the digest type to use. See DIGEST below.</dd><dt><strong>--base64</strong></dt><dd>emit base64-encoded digests, not hexadecimal</dd><dt><strong>-c</strong>, <strong>--check</strong></dt><dd>read checksums from the FILEs and check them</dd><dt><strong>-l</strong>, <strong>--length</strong>=<em>BITS</em></dt><dd>digest length in bits; must not exceed the max for the blake2 algorithm and must be a multiple of 8</dd><dt><strong>--raw</strong></dt><dd>emit a raw binary digest, not hexadecimal</dd><dt><strong>--tag</strong></dt><dd>create a BSD-style checksum (the default)</dd><dt><strong>--untagged</strong></dt><dd>create a reversed style checksum, without digest type</dd><dt><strong>-z</strong>, <strong>--zero</strong></dt><dd>end each output line with NUL, not newline, and disable file name escaping</dd></dl><h3 id="the-following-five-options-are-useful-only-when-verifying-checksums" tabindex="-1">The following five options are useful only when verifying checksums: <a class="header-anchor" href="#the-following-five-options-are-useful-only-when-verifying-checksums" aria-label="Permalink to &quot;The following five options are useful only when verifying checksums:&quot;">​</a></h3><dl><dt><strong>--ignore-missing</strong></dt><dd>don&#39;t fail or report status for missing files</dd><dt><strong>--quiet</strong></dt><dd>don&#39;t print OK for each successfully verified file</dd><dt><strong>--status</strong></dt><dd>don&#39;t output anything, status code shows success</dd><dt><strong>--strict</strong></dt><dd>exit non-zero for improperly formatted checksum lines</dd><dt><strong>-w</strong>, <strong>--warn</strong></dt><dd>warn about improperly formatted checksum lines</dd><dt><strong>--debug</strong></dt><dd>indicate which implementation used</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h3 id="digest-determines-the-digest-algorithm-and-default-output-format" tabindex="-1">DIGEST determines the digest algorithm and default output format: <a class="header-anchor" href="#digest-determines-the-digest-algorithm-and-default-output-format" aria-label="Permalink to &quot;DIGEST determines the digest algorithm and default output format:&quot;">​</a></h3><dl><dt>sysv</dt><dd>(equivalent to sum <strong>-s</strong>)</dd><dt>bsd</dt><dd>(equivalent to sum <strong>-r</strong>)</dd><dt>crc</dt><dd>(equivalent to cksum)</dd><dt>md5</dt><dd>(equivalent to md5sum)</dd><dt>sha1</dt><dd>(equivalent to sha1sum)</dd><dt>sha224</dt><dd>(equivalent to sha224sum)</dd><dt>sha256</dt><dd>(equivalent to sha256sum)</dd><dt>sha384</dt><dd>(equivalent to sha384sum)</dd><dt>sha512</dt><dd>(equivalent to sha512sum)</dd><dt>blake2b</dt><dd>(equivalent to b2sum)</dd><dt>sm3</dt><dd>(only available through cksum)</dd></dl><p>When checking, the input should be a former output of this program, or equivalent standalone program.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Padraig Brady and Q. Frank Xia.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/cksum%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/cksum\\</a>&gt; <br> or available locally via: info &#39;(coreutils) cksum invocation&#39;</p>',22);function u(t,h,m,c,g,p){return a(),d("div",null,[s("h1",i,o(t.$params.man),1),l])}const b=e(n,[["render",u]]);export{k as __pageData,b as default};
